import { BadRequestException, ConflictException } from '@nestjs/common';

// Only messages explicitly generated by our input validation are safe to display.
export class AdminInputError extends Error {}

export function adminCliErrorMessages(error: unknown): string[] {
  if (error instanceof AdminInputError) return [error.message];
  if (error instanceof BadRequestException) {
    const response = error.getResponse();
    if (typeof response === 'object' && 'message' in response) {
      const message: unknown = response.message;
      if (
        Array.isArray(message) &&
        message.every((item) => typeof item === 'string')
      )
        return message;
    }
  }
  if (error instanceof ConflictException)
    return ['Ya existe un administrador; no se modificó ninguna cuenta.'];
  if (
    error &&
    typeof error === 'object' &&
    'code' in error &&
    error.code === 11000
  ) {
    return [
      'Ya existe una cuenta con ese username o email; no se modificó ninguna cuenta.',
    ];
  }
  // Never dump driver messages: they may include connection strings or document contents.
  return [
    'Revisa que MongoDB esté encendido y la configuración local sea correcta.',
  ];
}
